const CrewRosterButton = ({ combatant, actionPoints, portraitPath, selected, selectable, onSelect }: {
  combatant: Combatant;
  actionPoints: number;
  portraitPath: string | null;
  selected: boolean;
  selectable: boolean;
  onSelect: () => void;
}) => {
  const [failedPortraitPath, setFailedPortraitPath] = useState<string | null>(null);
  const showPortrait = portraitPath && failedPortraitPath !== portraitPath;
  const actionLabel = combatant.defeated ? "Incapacitated" : selectable ? `${actionPoints} AP available` : "Activation complete";
  const woundLabel = combatant.woundState === "healthy" ? "healthy" : combatant.woundState === "light" ? "light wound" : combatant.woundState === "dead" ? "dead" : `${combatant.woundState} wound`;
  const woundBadge = woundBadgeFor(combatant.woundState);

  return (
    <button
      type="button"
      disabled={!selectable}
      onClick={onSelect}
      aria-label={`Select ${combatant.name}, ${woundLabel}, ${actionLabel}`}
      aria-pressed={selected}
      title={`${combatant.name} · ${woundLabel} · ${actionLabel}`}
      className={`group relative flex h-14 w-16 shrink-0 flex-col items-center justify-end border p-1 transition-colors ${selected ? "border-cyan-200 bg-cyan-300/20 text-cyan-50 shadow-[0_0_12px_rgba(103,232,249,0.35)]" : "border-(--hud-border) bg-(--hud-bg)/90 text-(--hud-text-dim) hover:border-cyan-300 hover:text-(--hud-text)"} disabled:cursor-not-allowed disabled:grayscale disabled:opacity-45`}
    >
      <span className="relative mb-0.5 h-8 w-8 overflow-hidden rounded-sm border border-(--hud-border-subtle) bg-black/50">
        {showPortrait ? (
          <Image src={portraitPath} alt="" fill sizes="32px" onError={() => setFailedPortraitPath(portraitPath)} className="object-cover" />
        ) : (
          <span className="flex h-full w-full items-center justify-center text-[12px] font-bold uppercase text-(--hud-text-dim)">{combatant.name.slice(0, 1)}</span>
        )}
        {woundBadge === "light" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-amber-300 bg-amber-950 text-amber-100"><Bandage size={8} strokeWidth={3} /></span>}
        {woundBadge === "serious" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-red-300 bg-red-950 text-red-100"><TriangleAlert size={8} strokeWidth={3} /></span>}
        {woundBadge === "dead" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-slate-300 bg-black text-slate-100"><Skull size={8} strokeWidth={3} /></span>}
      </span>
      <span className="w-full truncate text-center text-[7px] font-bold leading-none">{combatant.name}</span>
      <span className={`absolute right-0.5 top-0.5 min-w-5 border px-0.5 text-center text-[7px] font-bold ${selectable ? "border-emerald-300/70 bg-emerald-950 text-emerald-100" : "border-slate-500 bg-slate-950 text-slate-400"}`}>{actionPoints} AP</span>
    </button>
  );
};

const EnemyRosterButton = ({ combatant, selected, selectable, observed, morale, onSelect }: {
  combatant: Combatant;
  selected: boolean;
  selectable: boolean;
  observed: boolean;
  morale: string;
  onSelect: () => void;
}) => {
  const woundBadge = observed ? woundBadgeFor(combatant.woundState) : null;
  const statusLabel = !observed ? "Last known" : combatant.surrendered ? "Surrendered" : combatant.defeated ? combatant.woundState === "dead" ? "Dead" : "Incapacitated" : morale;
  return <button type="button" disabled={!selectable} onClick={onSelect} aria-label={`${selectable ? "Target" : "Enemy"} ${combatant.name}, ${statusLabel}`} aria-pressed={selected} title={`${combatant.name} · ${statusLabel}${observed ? ` · MF ${combatant.meleeRating}` : ""}`} className={`group relative flex h-14 w-16 shrink-0 flex-col items-center justify-end border p-1 transition-colors ${selected ? "border-red-200 bg-red-300/20 text-red-50 shadow-[0_0_12px_rgba(248,113,113,0.35)]" : observed ? "border-red-400/60 bg-red-950/70 text-red-100 hover:border-red-200" : "border-slate-500/60 bg-slate-950/80 text-slate-400"} disabled:cursor-not-allowed ${observed && !combatant.defeated && !combatant.surrendered ? "disabled:opacity-65" : "disabled:grayscale disabled:opacity-45"}`}>
    <span className="relative mb-0.5 flex h-8 w-8 items-center justify-center overflow-hidden rounded-sm border border-red-400/40 bg-black/60 text-[12px] font-bold uppercase">{observed ? combatant.name.slice(0, 1) : "?"}
      {woundBadge === "light" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-amber-300 bg-amber-950 text-amber-100"><Bandage size={8} strokeWidth={3} /></span>}
      {woundBadge === "serious" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-red-300 bg-red-950 text-red-100"><TriangleAlert size={8} strokeWidth={3} /></span>}
      {woundBadge === "dead" && <span aria-hidden="true" className="absolute bottom-0 left-0 flex h-3 w-3 items-center justify-center border border-slate-300 bg-black text-slate-100"><Skull size={8} strokeWidth={3} /></span>}
    </span>
    <span className="w-full truncate text-center text-[7px] font-bold leading-none">{observed ? combatant.name : "Last known"}</span>
    <span className="w-full truncate text-center text-[6px] uppercase leading-none opacity-80">{statusLabel}</span>
    {observed && <span className="absolute right-0.5 top-0.5 min-w-5 border border-red-400/50 bg-red-950 px-0.5 text-center text-[7px] font-bold text-red-100">MF {combatant.meleeRating}</span>}
  </button>;
};

