  const reachable = useMemo(() => selectedEnteredEnemySquare ? new Map() : combat.diveTargeting && scenario && selectedCombatantId ? diveOptions(scenario, selectedCombatantId) : status === "active" && scenario && selectedCombatantId && selectedIsProne && !selectedHasActed ? reachableCrawling(scenario, selectedCombatantId, selectedActionPoints) : status === "active" && scenario && selectedCombatantId && !selectedHasActed ? scenario.gravityMode === "zero-g" ? selectedActionPoints >= 3 ? zeroGravityPushes(scenario, selectedCombatantId) : new Map() : reachableMovement(scenario, selectedCombatantId, normalMovementAllowance, selectedIsTrotting, normalMovementMaxSteps) : new Map(), [combat.diveTargeting, normalMovementAllowance, normalMovementMaxSteps, scenario, selectedActionPoints, selectedCombatantId, selectedEnteredEnemySquare, selectedHasActed, selectedIsProne, selectedIsTrotting, status]);
