                {plannedExtinguishFire && <><div className={`font-bold ${criticalFireKeys.has(pointKey(plannedExtinguishFire)) ? "text-yellow-200" : "text-orange-200"}`}>Extinguish {criticalFireKeys.has(pointKey(plannedExtinguishFire)) ? "critical " : ""}fire at {plannedExtinguishFire.x},{plannedExtinguishFire.y} · smoke clears next turn</div><div className="grid grid-cols-2 gap-1"><button type="button" onClick={() => dispatch(confirmExtinguishFire())} className={`${primaryButton} border-orange-300 text-orange-100`}>Confirm · 3 AP</button><button type="button" onClick={() => dispatch(cancelExtinguishFire())} className={`${primaryButton} border-(--hud-border) text-(--hud-text-dim)`}>Cancel</button></div></>}
